insert into public.news_stories
  (slug, legacy_id, story_date, sort_order, title, source, url, summary, implications, tags, pinned, status)
values
  ('2026-10-21-korn-ferry-talent-trends-2027-capability-gaps-not-talent', '2026-10-21-0', '2026-10-21'::date, 0, 'Korn Ferry Talent Trends 2027: capability gaps, not talent shortages, will define 2027', 'Korn Ferry', 'https://www.kornferry.com/about-us/press/korn-ferry-report-ai-and-capability-gaps-will-reshape-talent-in-2027', 'Korn Ferry surveyed more than 1,300 talent and senior leaders in over 75 countries for its 13th annual report. 77% say capability gaps will be a bigger problem than talent shortages. Leaders rank adaptability as the top skill for 2027, then critical thinking and collaboration. 91% expect employees to own more of their development, 87% say lateral moves will count as much as promotions, and 67% expect people to move across projects rather than sit in fixed roles.', 'If sideways moves are valued as much as promotions, a stretch project in another team becomes a real career step rather than a detour, and it is a way to build evidence of adaptability. Most leaders now expect people to drive their own development, so waiting for a formal plan is a risk. 78% of leaders also say too few people are ready for how work will be done.', ARRAY['skills development', 'workforce transformation', 'research and insights']::text[], false, 'published'),
  ('2026-10-21-ai-fails-to-pay-off-because-it-is-deployed-inside-silos', '2026-10-21-1', '2026-10-21'::date, 1, 'AI fails to pay off because it is deployed inside silos', 'Harvard Business Review', 'https://hbr.org/2026/10/the-deployment-failure-holding-back-your-ai-investments', 'Hastings (University of Washington), Syverson (Chicago Booth) and Zimmerman (Yale SOM) pull together prior evidence. An NBER survey of about 6,000 executives found roughly nine in ten saw no measurable productivity effect from AI, and McKinsey found only 39% of AI-using firms report profit impact. Their diagnosis is that tools are tuned to tasks within one function, while the gains sit in the handoffs between functions.', 'The scarce, valuable work is redesigning the handoffs between teams, not making one task faster. Knowing how the teams upstream and downstream of you work is what lets you turn a local pilot into a change that pays off for the business. This is a synthesis of existing evidence rather than a new study.', ARRAY['workforce transformation', 'leadership and culture']::text[], false, 'published'),
  ('2026-10-20-how-ai-erodes-teamwork-people-who-ask-ai-instead-of', '2026-10-20-0', '2026-10-20'::date, 0, 'How AI erodes teamwork: people who ask AI instead of colleagues trust each other less and coordinate worse', 'Harvard Business Review', 'https://hbr.org/2026/10/how-ai-erodes-teamwork', 'Gretchen Gavett’s HBR piece summarises research by Niederhoffer and colleagues at BetterUp Labs with Jeffrey Hancock of Stanford (published 15 October). A survey of more than 1,000 US workers found that people who ask AI instead of colleagues trust each other less and coordinate worse. The authors call this “relationslipping”: it wears down a team’s shared sense of who knows what, its “transactive memory”. Suggested responses are more asynchronous communication, building psychological safety, and using AI to prepare for conversations rather than to replace them.', 'Individual AI productivity gains may come at a cost to the team. Each quick question sent to a chatbot is a missed chance to show what you know and to learn who knows what, so try using AI to sharpen a question and then take it to the person. Treat it as a well-placed argument rather than settled evidence: four of the five authors work at BetterUp, a coaching vendor, and the findings come from a survey rather than an experiment.', ARRAY['workforce transformation', 'leadership and culture', 'research and insights']::text[], false, 'published'),
  ('2026-10-20-personality-and-pay-shape-each-other-over-time', '2026-10-20-1', '2026-10-20'::date, 1, 'Personality and pay shape each other over time', 'Psychological Bulletin', 'https://doi.org/10.1037/bul0000526', 'A preregistered meta-analysis by Li, Yu, Yang, Zhang and colleagues, “Do Money and Time Change Who You Are?”, covers 11 long-running panel studies in the US, Germany, the Netherlands, Norway and Australia, with up to 134,515 working adults. Increases in conscientiousness and emotional stability predicted later pay rises. Pay rises were in turn followed by small gains in those same traits and small drops in agreeableness and extraversion. The effects were small, peaked about 1.2–1.4 years later, and the data are observational.', 'Traits can change, and the two most linked to later pay are dependability and composure under pressure, both worth working on deliberately. As you advance, check whether you are becoming less warm or less social, because the data suggest that drift tends to come with higher pay. First reported on 20 October by PsyPost; the journal’s own online date could not be confirmed.', ARRAY['skills development', 'research and insights']::text[], false, 'published'),
  ('2026-10-19-role-clarity-is-the-strongest-burnout-predictor-that', '2026-10-19-0', '2026-10-19'::date, 0, 'Role clarity is the strongest burnout predictor that organisations directly control (European researchers)', 'Frontiers in Public Health', 'https://www.frontiersin.org/journals/public-health/articles/10.3389/fpubh.2026.1900453/full', 'Noe, Wild, Mol and Guseva Canu surveyed 4,026 junior and senior European researchers and explained about half the variation in burnout. Resilience ranked first, then role clarity, then work–family conflict, then work stress, though the authors note that resilience overlaps with burnout itself. “Illegitimate tasks”, work that falls outside your role, weighed more heavily on senior staff. The authors conclude that structural fixes such as clearer roles and sustainable workloads look more promising than individual coping programmes. The design is cross-sectional, so it does not prove cause.', 'If you are running low, fixing an unclear role may help more than another resilience course. Get explicit agreement on what you own and what success looks like, and push back on tasks that are not part of your job before they pile up. For organisations, poor role design shows up as individual burnout.', ARRAY['leadership and culture', 'research and insights']::text[], false, 'published'),
  ('2026-10-14-hr-whitewashing-uk-employees-see-a-gap-between-what-their', '2026-10-14-0', '2026-10-14'::date, 0, '“HR whitewashing”: UK employees see a gap between what their employer says and what it does', 'Nottingham Trent University', 'https://www.emerald.com/er/article/doi/10.1108/ER-01-2026-0016/1399327/HR-whitewashing-employee-perceptions-of-policy', 'Whysall and colleagues at Nottingham Business School surveyed over 1,170 UK employees at medium and large organisations for Employee Relations. 53% saw a mismatch between wellbeing policies and how people actually behave, 44% saw one between DEI policy and practice, and 19% said the culture did not match the stated values. Staff believed commitments only when leaders’ behaviour and hiring and promotion decisions matched them. Phys.org covered the study on 14 October 2026.', 'To read your own environment, look at what actually happens: who gets promoted, how workloads are handled, and what happens when someone behaves badly, rather than the policy page. Those observed signals are a better guide to where to put your effort, or whether to stay. It mirrors the pilot-to-production gap: stated commitments that behaviour does not back.', ARRAY['leadership and culture', 'research and insights']::text[], false, 'published'),
  ('2026-10-14-oecd-shortages-are-concentrated-in-high-skilled-jobs', '2026-10-14-1', '2026-10-14'::date, 1, 'OECD: shortages are concentrated in high-skilled jobs, cognitive abilities and deep knowledge areas', 'OECD', 'https://www.oecd.org/en/publications/mapping-skill-shortages-in-oecd-countries_735f9485-en.html', 'Mapping Skill Shortages in OECD Countries, from the Getting Skills Right series, covers 38 countries using the Skills for Jobs Database. The most persistent shortages are in ICT, health, engineering and teaching roles, and in specific knowledge such as computers and electronics, medicine, and cognitive abilities. Physical abilities are in balance. The report also says generative AI may reduce demand for junior workers while demand for experienced workers holds steady. Launched on 14 October 2026.', 'Deep knowledge in a domain plus strong analytical ability is where demand is outrunning supply, so building in that direction pays off. Early-career workers should push for stretch work that gives them experience faster, since entry-level work is the part most exposed to AI.', ARRAY['skills development', 'macro signals', 'research and insights']::text[], false, 'published')
on conflict (slug) do update set
  legacy_id    = excluded.legacy_id,
  story_date   = excluded.story_date,
  sort_order   = excluded.sort_order,
  title        = excluded.title,
  source       = excluded.source,
  url          = excluded.url,
  summary      = excluded.summary,
  implications = excluded.implications,
  tags         = excluded.tags,
  pinned       = excluded.pinned,
  status       = excluded.status;

-- Nothing in this batch is merged away; clear any pointer left by a
-- previous run so the file stays the source of truth.
update public.news_stories set merged_into = null
 where slug in ('2026-10-21-korn-ferry-talent-trends-2027-capability-gaps-not-talent', '2026-10-21-ai-fails-to-pay-off-because-it-is-deployed-inside-silos', '2026-10-20-how-ai-erodes-teamwork-people-who-ask-ai-instead-of', '2026-10-20-personality-and-pay-shape-each-other-over-time', '2026-10-19-role-clarity-is-the-strongest-burnout-predictor-that', '2026-10-14-hr-whitewashing-uk-employees-see-a-gap-between-what-their', '2026-10-14-oecd-shortages-are-concentrated-in-high-skilled-jobs') and merged_into is not null;

